INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Verteilung der Aufgaben ein zentraler Bestandteil im Fehlermanagement?', 2, '[{"text": "Ja", "correct": true, "because": "Sichert Fehlerbehebung"}, {"text": "Nein", "correct": false, "because": "Sie ist essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt die Verteilung der Aufgaben im Fehlermanagement?', 3, '[{"text": "Effiziente Fehlerbearbeitung ermöglichen", "correct": true, "because": "Fördert Koordination"}, {"text": "Projektziele neu definieren", "correct": false, "because": "Initiierungsschritt"}, {"text": "Kosten direkt senken", "correct": false, "because": "Nebenaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Aufgabenverteilung klärt Zuständigkeiten für Fehler. b) Sie erfolgt nur im Abschluss.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, fortlaufend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Verteilung der Aufgaben im Fehlermanagement?', 4, '[{"text": "Fehlerpriorität", "correct": true, "because": "Bestimmt Dringlichkeit"}, {"text": "Unklare Rollen", "correct": false, "because": "Erschwert Zuweisung"}, {"text": "Teamkompetenzen", "correct": true, "because": "Passen Aufgaben zu Fähigkeiten"}, {"text": "Verfügbarkeit", "correct": true, "because": "Beeinflusst Einsatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Fehlermanagement ohne Aufgabenverteilung effektiv sein?', 2, '[{"text": "Nein", "correct": true, "because": "Zuständigkeiten unklar"}, {"text": "Ja", "correct": false, "because": "Chaos droht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Verteilung der Aufgaben im Fehlermanagement?', 3, '[{"text": "Schnelle und gezielte Fehlerbehebung", "correct": true, "because": "Fördert Effizienz"}, {"text": "Projekt neu finanzieren", "correct": false, "because": "Auftraggeberaufgabe"}, {"text": "Zeitplan neu erstellen", "correct": false, "because": "Planungsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Aufgabenverteilung nur für große Fehler relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Fehler brauchen sie"}, {"text": "Ja", "correct": false, "because": "Universelle Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Verantwortung hat der Projektleiter bei der Aufgabenverteilung?', 3, '[{"text": "Zuweisung an geeignete Mitarbeiter", "correct": true, "because": "Sichert Kompetenz"}, {"text": "Fehler ignorieren", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Projektziele neu setzen", "correct": false, "because": "Auftraggeberaufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Aufgabenverteilung basiert auf Fehlermeldungen. b) Sie ist immer spontan.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, geplant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Verteilung der Aufgaben im Fehlermanagement?', 3, '[{"text": "Fehler bleiben unbearbeitet", "correct": true, "because": "Keine Zuweisung"}, {"text": "Fehlerbehebung wird schneller", "correct": false, "because": "Eher Verzögerung"}, {"text": "Qualität steigt", "correct": false, "because": "Probleme bleiben"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Aufgabenverteilung ohne Ticketsystem erfolgen?', 2, '[{"text": "Ja", "correct": true, "because": "Manuell möglich"}, {"text": "Nein", "correct": false, "because": "Werkzeug optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt Aufgabenverteilung im Fehlermanagement?', 3, '[{"text": "Anna behebt Bug #123", "correct": true, "because": "Klar und spezifisch"}, {"text": "Irgendwer behebt etwas", "correct": false, "because": "Zu vage"}, {"text": "Team soll Fehler suchen", "correct": false, "because": "Keine Zuweisung"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Aufgabenverteilung nur für technische Fehler relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch organisatorische Fehler"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kriterien beeinflussen die Verteilung?', 4, '[{"text": "Fehlerdringlichkeit", "correct": true, "because": "Setzt Priorität"}, {"text": "Unklare Meldungen", "correct": false, "because": "Erschwert Zuweisung"}, {"text": "Mitarbeiterfähigkeiten", "correct": true, "because": "Passen Kompetenz"}, {"text": "Fehlerart", "correct": true, "because": "Bestimmt Expertise"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die Aufgabenverteilung dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nachvollziehbarkeit wichtig"}, {"text": "Nein", "correct": false, "because": "Dokumentation hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug unterstützt die Aufgabenverteilung?', 3, '[{"text": "Jira für Fehlertickets", "correct": true, "because": "Verteilt Aufgaben"}, {"text": "Keine Struktur", "correct": false, "because": "Fehlt Übersicht"}, {"text": "Zufällige Liste", "correct": false, "because": "Unsystematisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Verteilung ohne Projektleiter erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Steuerung nötig"}, {"text": "Ja", "correct": false, "because": "Unkoordiniert unpraktisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erschwert die Aufgabenverteilung?', 3, '[{"text": "Unklare Fehlerbeschreibungen", "correct": true, "because": "Verhindern Zuweisung"}, {"text": "Klarer Prozess", "correct": false, "because": "Fördert Verteilung"}, {"text": "Gute Teamkompetenz", "correct": false, "because": "Unterstützt Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Verteilung optimiert Fehlerbehebung. b) Sie ist nur für IT-Fehler.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, breit anwendbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen der Aufgabenverteilung?', 3, '[{"text": "Schnelle Fehlerlösung", "correct": true, "because": "Fördert Effizienz"}, {"text": "Maximale Unklarheit", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Koordination", "correct": false, "because": "Fördert Zusammenarbeit"}]');
